    function teacherMetricsByCategory(row) {
      const all = [
        ["感染力分数", num(row["感染力分数"], 3)],
        ["开口时长", num(row["开口时长"], 1)],
        ["课中正确率", pct(row["课中正确率"])],
        ["上台平均数", num(row["上台平均数"], 1)],
        ["主动性", num(row["主动性"], 1)],
        ["镜头感", pct(row["镜头感"])],
        ["愉悦度", pct(row["愉悦度"])],
        ["有效互动次数", num(row["有效互动次数"], 1)],
        ["课前作业提醒", pct(row["课前作业提醒"])],
        ["课程预告", pct(row["课程预告"])],
        ["读题审题", pct(row["读题审题"])],
      ];
      if (state.category === "全部指标") return all;
      return all.filter(([name]) => metricCategoryMap[name] === state.category);
    }

    function renderTeacherTable() {
      let rows = applyTeacherFilter(payload.teachers);
      const headers = ["老师", "业务部门", "小组", "风险等级", "风险分", "重点问题", "样本课节数", "课中正确率", "镜头感", "愉悦度", "作业完成率", "预习率"];
      const html = `
        <thead><tr>${headers.map(h => `<th>${h}</th>`).join("")}</tr></thead>
        <tbody>${rows.map((r, idx) => `
          <tr>
            <td class="teacher-name" data-index="${idx}">${r["老师"]}</td>
            <td>${r["业务部门"]}</td>
            <td>${r["小组"]}</td>
            <td class="${riskClass(r["风险等级"])}">${r["风险等级"]}</td>
            <td>${num(r["风险分"], 1)}</td>
            <td>${r["重点问题"]}</td>
            <td>${r["样本课节数"]}</td>
            <td>${pct(r["课中正确率"])}</td>
            <td>${pct(r["镜头感"])}</td>
            <td>${pct(r["愉悦度"])}</td>
            <td>${pct(r["作业完成率"])}</td>
            <td>${pct(r["预习率"])}</td>
          </tr>`).join("")}
        </tbody>`;
      const table = document.getElementById("teacherTable");
      table.innerHTML = html;
      table.querySelectorAll(".teacher-name").forEach(cell => {
        cell.addEventListener("click", () => {
          const row = rows[Number(cell.dataset.index)];
          renderTeacherDrill(row);
        });
      });
    }

    function renderTeacherDrill(row) {
      const drill = document.getElementById("teacherDrill");
      const metricPills = teacherMetricsByCategory(row).map(([name, value]) => `<span class="metric-pill">${name}: ${value}</span>`).join("");
      const issues = row["重点问题"] === "整体稳定" ? ["整体状态稳定，可继续观察趋势。"] : row["重点问题"].split(" / ").map(v => `${v} 偏弱，需要优先复盘。`);
      const northstar = [
        ["课中首答正确率", pct(row["课中首答正确率"])],
        ["课中末答正确率", pct(row["课中末答正确率"])],
        ["课后首答正确率", pct(row["课后首答正确率"])],
        ["课后末答正确率", pct(row["课后末答正确率"])],
        ["作业完成率", pct(row["作业完成率"])],
        ["预习率", pct(row["预习率"])],
        ["小老师视频提交率", pct(row["小老师视频提交率"])],
      ];
      drill.innerHTML = `
        <div class="section-head">
          <div>
            <h3>${row["老师"]} · 老师下钻</h3>
            <p>${row["业务部门"]} / ${row["小组"]} · 风险等级：<span class="${riskClass(row["风险等级"])}">${row["风险等级"]}</span></p>
          </div>
        </div>
        <div class="drill-grid">
          <div class="mini-card">
            <h4>AI监课核心指标</h4>
            <div class="metric-pills">${metricPills}</div>
          </div>
          <div class="mini-card">
            <h4>当前重点问题</h4>
            <ul>${issues.map(i => `<li>${i}</li>`).join("")}</ul>
          </div>
          <div class="mini-card">
            <h4>北极星辅助结果</h4>
            <ul>${northstar.map(([k, v]) => `<li>${k}：${v}</li>`).join("")}</ul>
          </div>
        </div>
      `;
      drill.classList.add("active");
      drill.scrollIntoView({ behavior: "smooth", block: "nearest" });
    }

    function renderAll() {
      renderDeptTable();
      renderGroupTable();
      renderTeacherTable();
    }

    buildSummary();
    initFilters();
    renderAll();

    deptFilter.addEventListener("change", (e) => {
      state.dept = e.target.value;
      renderAll();
    });
    groupFilter.addEventListener("change", (e) => {
      state.group = e.target.value;
      renderAll();
    });
    categoryFilter.addEventListener("change", (e) => {
      state.category = e.target.value;
      renderTeacherTable();
    });
    teacherFilter.addEventListener("input", (e) => {
      state.teacherKeyword = e.target.value.trim();
      renderTeacherTable();
    });
